"""
Metadata-Aware Retrieval-Augmented Generation (RAG) System
===========================================================

Implements a RAG pipeline where document metadata is used for BOTH:

1. **Filtering** — structural predicates (equality, ranges, set membership,
   custom callables) applied over each document's ``metadata`` dict to select
   candidate documents *before* any relevance scoring; and

2. **Ranking** — relevance scores computed with hybrid dense + lexical
   retrieval, then adjusted by metadata signals (priority/authority boosts,
   recency decay) before the final ranked list is returned.

The module is self-contained (pure Python standard library by default) and
provides pluggable hooks so it can be wired to production embeddings
(e.g. ``sentence-transformers``, OpenAI embeddings) and LLM callables.

Run the built-in demonstration with::

    python rag_metadata_system.py
"""

from __future__ import annotations

import hashlib
import math
import re
from dataclasses import dataclass, field
from datetime import date, datetime, timezone
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence, Tuple

# ---------------------------------------------------------------------------
# Tokenization helpers
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+", re.IGNORECASE)

_STOPWORDS = frozenset(
    """
    a an and are as at be by for from has he her his in is it its
    of on or that the their them they this to was were will with
    what which who whom when where why how do does did not no nor
    but if than so too very can just should would could may might
    """.split()
)


def tokenize(text: str) -> List[str]:
    """Lower-case regex tokenizer with stopword removal."""
    return [tok for tok in _TOKEN_RE.findall(text.lower()) if tok not in _STOPWORDS]


# ---------------------------------------------------------------------------
# Embeddings and similarity
# ---------------------------------------------------------------------------


def _l2_normalize(vec: Sequence[float]) -> List[float]:
    norm = math.sqrt(sum(v * v for v in vec))
    if norm == 0.0:
        return [0.0] * len(vec)
    return [v / norm for v in vec]


class HashingVectorizer:
    """Deterministic signed hashing-trick bag-of-words embedder.

    Provides a dependency-free fallback so the system runs out of the box.
    Replace it with any dense embedder via ``MetadataAwareRAG(embed_fn=...)``.
    """

    def __init__(self, dim: int = 512, tokenizer: Callable[[str], List[str]] = tokenize) -> None:
        self.dim = dim
        self.tokenizer = tokenizer

    def embed(self, text: str) -> List[float]:
        counts: Dict[int, float] = {}
        for tok in self.tokenizer(text):
            digest = hashlib.blake2b(tok.encode("utf-8"), digest_size=16).digest()
            idx = int.from_bytes(digest[:8], "little") % self.dim
            sign = 1 if int.from_bytes(digest[8:], "little") % 2 == 0 else -1
            counts[idx] = counts.get(idx, 0.0) + sign
        return _l2_normalize([counts.get(i, 0.0) for i in range(self.dim)])


def cosine_similarity(a: Sequence[float], b: Sequence[float]) -> float:
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------


@dataclass
class Document:
    """A text chunk together with structured metadata used for filtering/ranking."""

    id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    embedding: Optional[List[float]] = None


@dataclass
class RetrievalResult:
    """A ranked retrieval hit with explainable score components."""

    document: Document
    score: float                 # final combined score
    dense_score: float           # semantic similarity (0..1)
    lexical_score: float         # BM25 score (raw)
    metadata_adjustment: float = 1.0  # multiplicative boost applied
    rank: int = 0

    @property
    def id(self) -> str:
        return self.document.id

    @property
    def text(self) -> str:
        return self.document.text


# ---------------------------------------------------------------------------
# Metadata filtering (structural predicates)
# ---------------------------------------------------------------------------

Predicate = Callable[[Dict[str, Any]], bool]


class MetadataFilter:
    """Composable structural predicate over a document's metadata dict.

    Usage::

        flt = (
            MetadataFilter.eq("category", "engineering")
            & MetadataFilter.range_("priority", 1, 3)
            & MetadataFilter.in_("region", ["eu", "us"])
        )
        docs = rag.retrieve("query", metadata_filter=flt)
    """

    def __init__(self, conditions: Sequence[Predicate] = ()) -> None:
        self.conditions: List[Predicate] = list(conditions)

    def __call__(self, metadata: Dict[str, Any]) -> bool:
        return all(pred(metadata) for pred in self.conditions)

    def __and__(self, other: "MetadataFilter") -> "MetadataFilter":
        return MetadataFilter(self.conditions + list(other.conditions))

    # -- static constructors ------------------------------------------------
    @staticmethod
    def eq(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter([lambda md, k=key, v=value: md.get(k) == v])

    @staticmethod
    def ne(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter([lambda md, k=key, v=value: k in md and md.get(k) != v])

    @staticmethod
    def in_(key: str, values: Sequence[Any]) -> "MetadataFilter":
        allowed = set(values)
        return MetadataFilter([lambda md, k=key, s=allowed: md.get(k) in s])

    @staticmethod
    def ge(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter(
            [lambda md, k=key, v=value: md.get(k) is not None and md.get(k) >= v]
        )

    @staticmethod
    def le(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter(
            [lambda md, k=key, v=value: md.get(k) is not None and md.get(k) <= v]
        )

    @staticmethod
    def range_(key: str, lo: Any, hi: Any) -> "MetadataFilter":
        return MetadataFilter(
            [lambda md, k=key, a=lo, b=hi: md.get(k) is not None and a <= md.get(k) <= b]
        )

    @staticmethod
    def exists(key: str) -> "MetadataFilter":
        return MetadataFilter([lambda md, k=key: k in md])

    @staticmethod
    def custom(predicate: Predicate) -> "MetadataFilter":
        return MetadataFilter([predicate])


# ---------------------------------------------------------------------------
# BM25 lexical index
# ---------------------------------------------------------------------------


class BM25Index:
    """Okapi BM25 sparse lexical index over the document collection."""

    def __init__(
        self,
        documents: Iterable[Document],
        tokenizer: Callable[[str], List[str]] = tokenize,
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        self.tokenizer = tokenizer
        self.k1 = k1
        self.b = b
        self.doc_lengths: Dict[str, int] = {}
        self.term_doc_freq: Dict[str, int] = {}
        self.term_freqs: Dict[str, Dict[str, int]] = {}  # term -> {doc_id: count}
        total_len = 0
        for doc in documents:
            terms = tokenizer(doc.text)
            counts: Dict[str, int] = {}
            for term in terms:
                counts[term] = counts.get(term, 0) + 1
            self.doc_lengths[doc.id] = len(terms)
            total_len += len(terms)
            for term, count in counts.items():
                self.term_doc_freq[term] = self.term_doc_freq.get(term, 0) + 1
                self.term_freqs.setdefault(term, {})[doc.id] = count
        self.doc_count = max(1, len(self.doc_lengths))
        self.avg_dl = total_len / self.doc_count if self.doc_count else 0.0

    def idf(self, term: str) -> float:
        n = self.term_doc_freq.get(term, 0)
        return math.log(1.0 + (self.doc_count - n + 0.5) / (n + 0.5))

    def score(self, query_terms: Sequence[str], doc_id: str) -> float:
        dl = self.doc_lengths.get(doc_id, 0)
        if dl == 0:
            return 0.0
        score = 0.0
        for term in set(query_terms):
            tf = self.term_freqs.get(term, {}).get(doc_id, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1 - self.b + self.b * dl / max(self.avg_dl, 1e-9))
            score += self.idf(term) * (tf * (self.k1 + 1)) / denom
        return score


# ---------------------------------------------------------------------------
# Metadata-aware RAG engine
# ---------------------------------------------------------------------------


class MetadataAwareRAG:
    """Metadata-aware RAG engine.

    Pipeline per query:

      1. (Optional) structural metadata filtering -> candidate documents.
      2. Dense similarity (pluggable embedder) + BM25 lexical scoring.
      3. Hybrid relevance score ``alpha * dense + (1 - alpha) * lexical_norm``.
      4. Metadata ranking adjustments (priority/authority boost, recency decay).
      5. Top-k selection with an optional relevance threshold.
      6. Prompt/context assembly with numbered citations and an optional LLM
         callback for grounded answer generation.
    """

    DEFAULT_PROMPT = (
        "Use only the context below to answer the question. "
        "Cite sources with [n] markers matching the numbered items. "
        "If the context does not contain the answer, say "
        "\"I don't have enough information.\"\n\n"
        "Context:\n{context}\n\nQuestion: {question}\n\nAnswer:"
    )

    def __init__(
        self,
        embed_fn: Optional[Callable[[str], List[float]]] = None,
        tokenizer: Callable[[str], List[str]] = tokenize,
        alpha: float = 0.6,
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        if embed_fn is None:
            embed_fn = HashingVectorizer().embed
        self.embed_fn = embed_fn
        self.tokenizer = tokenizer
        self.alpha = alpha  # weight of dense vs lexical in hybrid relevance
        self.k1 = k1
        self.b = b
        self._documents: Dict[str, Document] = {}
        self._bm25: Optional[BM25Index] = None

    # -- indexing -----------------------------------------------------------

    def add_document(self, document: Document) -> None:
        if not document.embedding:
            document.embedding = self.embed_fn(document.text)
        self._documents[document.id] = document
        self._bm25 = None  # lexical index invalidated; rebuilt lazily

    def add_documents(self, documents: Iterable[Document]) -> int:
        count = 0
        for doc in documents:
            self.add_document(doc)
            count += 1
        return count

    @property
    def documents(self) -> Dict[str, Document]:
        return dict(self._documents)

    def _ensure_bm25(self) -> BM25Index:
        if self._bm25 is None:
            self._bm25 = BM25Index(
                self._documents.values(), self.tokenizer, k1=self.k1, b=self.b
            )
        return self._bm25

    # -- retrieval ----------------------------------------------------------

    def retrieve(
        self,
        query: str,
        metadata_filter: Optional[MetadataFilter] = None,
        k: int = 5,
        min_score: float = 0.0,
        boost_fields: Optional[Dict[str, float]] = None,
        decay_date_key: Optional[str] = None,
        decay_half_life_days: float = 365.0,
        now: Optional[datetime] = None,
    ) -> List[RetrievalResult]:
        """Retrieve and rank documents for ``query``.

        Args:
            query: user query text.
            metadata_filter: structural predicate; documents failing it are
                excluded before scoring (metadata-based FILTERING).
            k: number of top results to return.
            min_score: drop results whose final score is below this threshold.
            boost_fields: metadata keys whose numeric values multiply the
                relevance score, e.g. ``{"priority": 0.15, "authority": 0.1}``
                (metadata-based RANKING).
            decay_date_key: metadata key holding an ISO date or epoch used for
                a recency-decay multiplier ``0.5 ** (age_days / half_life)``.
            decay_half_life_days: half life of the recency decay curve.
            now: reference time for decay (defaults to current UTC time).
        """
        candidates = self._select_candidates(metadata_filter)
        if not candidates:
            return []

        query_embedding = self.embed_fn(query)
        query_terms = self.tokenizer(query)
        bm25 = self._ensure_bm25()
        lexical_scores = {doc.id: bm25.score(query_terms, doc.id) for doc in candidates}
        max_lex = max(lexical_scores.values()) if lexical_scores else 0.0

        results: List[RetrievalResult] = []
        for doc in candidates:
            dense = cosine_similarity(query_embedding, doc.embedding or [])
            lex = lexical_scores.get(doc.id, 0.0)
            lex_norm = lex / max_lex if max_lex > 0.0 else 0.0
            relevance = self.alpha * dense + (1.0 - self.alpha) * lex_norm

            adjustment = 1.0
            adjustment *= self._metadata_boost(doc.metadata, boost_fields or {})
            if decay_date_key is not None:
                adjustment *= self._recency_decay(
                    doc.metadata, decay_date_key, decay_half_life_days, now
                )

            final_score = relevance * adjustment
            if final_score >= min_score:
                results.append(
                    RetrievalResult(
                        document=doc,
                        score=final_score,
                        dense_score=dense,
                        lexical_score=lex,
                        metadata_adjustment=adjustment,
                    )
                )

        results.sort(key=lambda r: r.score, reverse=True)
        ranked = results[:k]
        for rank, res in enumerate(ranked, start=1):
            res.rank = rank
        return ranked

    def _select_candidates(
        self, metadata_filter: Optional[MetadataFilter]
    ) -> List[Document]:
        if metadata_filter is None:
            return list(self._documents.values())
        return [doc for doc in self._documents.values() if metadata_filter(doc.metadata)]

    # -- metadata ranking helpers -------------------------------------------

    @staticmethod
    def _metadata_boost(metadata: Dict[str, Any], boost_fields: Dict[str, float]) -> float:
        multiplier = 1.0
        for key, weight in boost_fields.items():
            value = metadata.get(key)
            if value is None:
                continue
            if isinstance(value, bool):
                multiplier *= 1.0 + weight if value else 1.0
            elif isinstance(value, (int, float)):
                multiplier *= 1.0 + weight * float(value)
        return multiplier

    @staticmethod
    def _parse_date(value: Any) -> Optional[datetime]:
        if isinstance(value, datetime):
            return value
        if isinstance(value, date):
            return datetime(value.year, value.month, value.day)
        if isinstance(value, (int, float)):
            try:
                return datetime.fromtimestamp(value)
            except (OverflowError, OSError, ValueError):
                return None
        if isinstance(value, str):
            text = value.strip()
            try:
                return datetime.fromisoformat(text)
            except ValueError:
                try:
                    return datetime.strptime(text, "%Y-%m-%d")
                except ValueError:
                    return None
        return None

    @classmethod
    def _recency_decay(
        cls,
        metadata: Dict[str, Any],
        date_key: str,
        half_life_days: float,
        now: Optional[datetime] = None,
    ) -> float:
        dt = cls._parse_date(metadata.get(date_key))
        if dt is None:
            return 1.0
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        ref = now or datetime.now(timezone.utc)
        if ref.tzinfo is None:
            ref = ref.replace(tzinfo=timezone.utc)
        age_days = max(0.0, (ref - dt).total_seconds() / 86400.0)
        return 0.5 ** (age_days / half_life_days)

    # -- answer generation --------------------------------------------------

    def format_context(self, results: Sequence[RetrievalResult], max_chars: int = 6000) -> str:
        parts: List[str] = []
        used = 0
        for i, res in enumerate(results, start=1):
            if used >= max_chars:
                break
            snippet = res.text.strip()
            if not snippet:
                continue
            parts.append(
                f"[{i}] (id={res.id}, metadata={res.document.metadata})\n{snippet}"
            )
            used += len(snippet)
        return "\n\n".join(parts)

    def answer(
        self,
        query: str,
        metadata_filter: Optional[MetadataFilter] = None,
        k: int = 5,
        llm: Optional[Callable[[str], str]] = None,
        prompt_template: Optional[str] = None,
        **retrieve_kwargs: Any,
    ) -> Dict[str, Any]:
        """End-to-end RAG query: retrieve, assemble context, generate answer.

        If ``llm`` is None a deterministic extractive fallback answer is
        produced from the top-ranked passages (each sentence tagged with its
        source citation), so the pipeline works without an external model.
        """
        results = self.retrieve(
            query, metadata_filter=metadata_filter, k=k, **retrieve_kwargs
        )
        context = self.format_context(results)
        template = prompt_template or self.DEFAULT_PROMPT
        prompt = template.format(context=context, question=query)

        if llm is not None:
            answer_text = llm(prompt)
        else:
            answer_text = self._extractive_answer(query, results)

        return {
            "question": query,
            "answer": answer_text,
            "context": context,
            "prompt": prompt,
            "results": results,
            "citations": [
                res.document.metadata.get("source", res.id) for res in results
            ],
            "filter": metadata_filter,
        }

    @staticmethod
    def _extractive_answer(query: str, results: Sequence[RetrievalResult]) -> str:
        """Ground the answer in the retrieved passages with citations."""
        query_tokens = tokenize(query)[:6]
        sentences: List[Tuple[str, int]] = []
        for idx, res in enumerate(results, start=1):
            for sent in re.split(r"(?<=[.!?])\s+", res.text.strip()):
                lowered = sent.lower()
                if len(sent) > 25 and any(tok in lowered for tok in query_tokens):
                    sentences.append((sent, idx))
        if not sentences:
            return "I don't have enough information in the retrieved context to answer."
        seen = set()
        unique: List[str] = []
        for sent, idx in sentences:
            key = sent.lower()
            if key not in seen:
                seen.add(key)
                unique.append(f"- {sent} [source {idx}]")
        return "Based on the retrieved documents:\n" + "\n".join(unique[:5])


# ---------------------------------------------------------------------------
# Demonstration
# ---------------------------------------------------------------------------


def _demo() -> None:
    docs = [
        Document(
            id="doc-001",
            text=(
                "In production RAG pipelines you should apply metadata filters before "
                "vector ranking, so that semantic search only sees documents from the "
                "allowed category, region and priority range. Filtering first shrinks the "
                "candidate set and makes ranking faster and more accurate."
            ),
            metadata={
                "category": "engineering",
                "region": "eu",
                "priority": 3,
                "authority": 2,
                "source": "runbooks/rag-best-practices.md",
                "published": "2024-03-15",
            },
        ),
        Document(
            id="doc-002",
            text=(
                "A recursive character text splitter cuts documents into chunks of around "
                "1000 tokens with 200 tokens of overlap so context is preserved across "
                "chunk boundaries. Chunk size has a direct impact on retrieval quality."
            ),
            metadata={
                "category": "engineering",
                "region": "us",
                "priority": 1,
                "authority": 1,
                "source": "guides/chunking.md",
                "published": "2023-11-02",
            },
        ),
        Document(
            id="doc-003",
            text=(
                "Vector databases such as Chroma, Weaviate, and Qdrant store document "
                "embeddings and answer similarity queries with approximate nearest "
                "neighbour search. Many of them support metadata filters natively."
            ),
            metadata={
                "category": "data-science",
                "region": "us",
                "priority": 2,
                "authority": 1,
                "source": "notes/vector-databases.md",
                "published": "2024-01-20",
            },
        ),
        Document(
            id="doc-004",
            text=(
                "Metadata-aware ranking multiplies the base relevance score by signals "
                "such as document priority, authority and recency. A recency decay of "
                "0.5 per half-life keeps stale documents from outranking fresh guidance."
            ),
            metadata={
                "category": "engineering",
                "region": "eu",
                "priority": 3,
                "authority": 3,
                "source": "runbooks/metadata-ranking.md",
                "published": "2024-06-10",
            },
        ),
        Document(
            id="doc-005",
            text=(
                "Multi-query retrieval generates several paraphrases of the user question "
                "and unions the results, which improves recall but can also surface "
                "irrelevant documents unless the candidates are re-ranked."
            ),
            metadata={
                "category": "research",
                "region": "global",
                "priority": 1,
                "authority": 1,
                "source": "notes/retrieval-strategies.md",
                "published": "2024-02-05",
            },
        ),
    ]

    rag = MetadataAwareRAG(embed_fn=HashingVectorizer(dim=1024).embed)
    rag.add_documents(docs)

    query = "How do I use metadata filters before ranking?"

    print("== Retrieval without metadata filter ==")
    for r in rag.retrieve(query, k=3):
        print(
            f"  rank={r.rank} id={r.id} score={r.score:.3f} "
            f"(dense={r.dense_score:.3f}, lexical={r.lexical_score:.2f}, "
            f"adjust={r.metadata_adjustment:.2f})"
        )

    flt = (
        MetadataFilter.eq("category", "engineering")
        & MetadataFilter.eq("region", "eu")
        & MetadataFilter.range_("priority", 2, 5)
    )
    print("\n== Retrieval with metadata filter (category=engineering, region=eu, priority>=2) ==")
    for r in rag.retrieve(query, metadata_filter=flt, k=3):
        print(f"  rank={r.rank} id={r.id} score={r.score:.3f} (dense={r.dense_score:.3f})")

    print("\n== Retrieval with metadata-boosted ranking ==")
    for r in rag.retrieve(
        query,
        metadata_filter=MetadataFilter.eq("category", "engineering"),
        k=3,
        boost_fields={"priority": 0.15, "authority": 0.10},
        decay_date_key="published",
        decay_half_life_days=180,
    ):
        print(
            f"  rank={r.rank} id={r.id} score={r.score:.3f} "
            f"adjust={r.metadata_adjustment:.2f} "
            f"published={r.document.metadata['published']}"
        )

    print("\n== End-to-end answer (extractive fallback, no external LLM needed) ==")
    result = rag.answer(query, metadata_filter=flt, k=3)
    print(result["answer"])
    print("\nCitations:", result["citations"])


if __name__ == "__main__":
    _demo()

"""
Metadata-Aware Retrieval-Augmented Generation (RAG) System
===========================================================

Implements a RAG pipeline where document metadata is used for BOTH:

1. **Filtering** — structural predicates (equality, ranges, set membership,
   custom callables) applied over each document's ``metadata`` dict to select
   candidate documents *before* any relevance scoring; and

2. **Ranking** — relevance scores computed with hybrid dense + lexical
   retrieval, then adjusted by metadata signals (priority/authority boosts,
   recency decay) before the final ranked list is returned.

The module is self-contained (pure Python standard library by default) and
provides pluggable hooks so it can be wired to production embeddings
(e.g. ``sentence-transformers``, OpenAI embeddings) and LLM callables.

Run the built-in demonstration with::

    python rag_metadata_system.py
"""

from __future__ import annotations

import hashlib
import math
import re
from dataclasses import dataclass, field
from datetime import date, datetime, timezone
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence, Tuple

# ---------------------------------------------------------------------------
# Tokenization helpers
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+", re.IGNORECASE)

_STOPWORDS = frozenset(
    """
    a an and are as at be by for from has he her his in is it its
    of on or that the their them they this to was were will with
    what which who whom when where why how do does did not no nor
    but if than so too very can just should would could may might
    """.split()
)


def tokenize(text: str) -> List[str]:
    """Lower-case regex tokenizer with stopword removal."""
    return [tok for tok in _TOKEN_RE.findall(text.lower()) if tok not in _STOPWORDS]


# ---------------------------------------------------------------------------
# Embeddings and similarity
# ---------------------------------------------------------------------------


def _l2_normalize(vec: Sequence[float]) -> List[float]:
    norm = math.sqrt(sum(v * v for v in vec))
    if norm == 0.0:
        return [0.0] * len(vec)
    return [v / norm for v in vec]


class HashingVectorizer:
    """Deterministic signed hashing-trick bag-of-words embedder.

    Provides a dependency-free fallback so the system runs out of the box.
    Replace it with any dense embedder via ``MetadataAwareRAG(embed_fn=...)``.
    """

    def __init__(self, dim: int = 512, tokenizer: Callable[[str], List[str]] = tokenize) -> None:
        self.dim = dim
        self.tokenizer = tokenizer

    def embed(self, text: str) -> List[float]:
        counts: Dict[int, float] = {}
        for tok in self.tokenizer(text):
            digest = hashlib.blake2b(tok.encode("utf-8"), digest_size=16).digest()
            idx = int.from_bytes(digest[:8], "little") % self.dim
            sign = 1 if int.from_bytes(digest[8:], "little") % 2 == 0 else -1
            counts[idx] = counts.get(idx, 0.0) + sign
        return _l2_normalize([counts.get(i, 0.0) for i in range(self.dim)])


def cosine_similarity(a: Sequence[float], b: Sequence[float]) -> float:
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------


@dataclass
class Document:
    """A text chunk together with structured metadata used for filtering/ranking."""

    id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    embedding: Optional[List[float]] = None


@dataclass
class RetrievalResult:
    """A ranked retrieval hit with explainable score components."""

    document: Document
    score: float                 # final combined score
    dense_score: float           # semantic similarity (0..1)
    lexical_score: float         # BM25 score (raw)
    metadata_adjustment: float = 1.0  # multiplicative boost applied
    rank: int = 0

    @property
    def id(self) -> str:
        return self.document.id

    @property
    def text(self) -> str:
        return self.document.text


# ---------------------------------------------------------------------------
# Metadata filtering (structural predicates)
# ---------------------------------------------------------------------------

Predicate = Callable[[Dict[str, Any]], bool]


class MetadataFilter:
    """Composable structural predicate over a document's metadata dict.

    Usage::

        flt = (
            MetadataFilter.eq("category", "engineering")
            & MetadataFilter.range_("priority", 1, 3)
            & MetadataFilter.in_("region", ["eu", "us"])
        )
        docs = rag.retrieve("query", metadata_filter=flt)
    """

    def __init__(self, conditions: Sequence[Predicate] = ()) -> None:
        self.conditions: List[Predicate] = list(conditions)

    def __call__(self, metadata: Dict[str, Any]) -> bool:
        return all(pred(metadata) for pred in self.conditions)

    def __and__(self, other: "MetadataFilter") -> "MetadataFilter":
        return MetadataFilter(self.conditions + list(other.conditions))

    # -- static constructors ------------------------------------------------
    @staticmethod
    def eq(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter([lambda md, k=key, v=value: md.get(k) == v])

    @staticmethod
    def ne(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter([lambda md, k=key, v=value: k in md and md.get(k) != v])

    @staticmethod
    def in_(key: str, values: Sequence[Any]) -> "MetadataFilter":
        allowed = set(values)
        return MetadataFilter([lambda md, k=key, s=allowed: md.get(k) in s])

    @staticmethod
    def ge(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter(
            [lambda md, k=key, v=value: md.get(k) is not None and md.get(k) >= v]
        )

    @staticmethod
    def le(key: str, value: Any) -> "MetadataFilter":
        return MetadataFilter(
            [lambda md, k=key, v=value: md.get(k) is not None and md.get(k) <= v]
        )

    @staticmethod
    def range_(key: str, lo: Any, hi: Any) -> "MetadataFilter":
        return MetadataFilter(
            [lambda md, k=key, a=lo, b=hi: md.get(k) is not None and a <= md.get(k) <= b]
        )

    @staticmethod
    def exists(key: str) -> "MetadataFilter":
        return MetadataFilter([lambda md, k=key: k in md])

    @staticmethod
    def custom(predicate: Predicate) -> "MetadataFilter":
        return MetadataFilter([predicate])


# ---------------------------------------------------------------------------
# BM25 lexical index
# ---------------------------------------------------------------------------


class BM25Index:
    """Okapi BM25 sparse lexical index over the document collection."""

    def __init__(
        self,
        documents: Iterable[Document],
        tokenizer: Callable[[str], List[str]] = tokenize,
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        self.tokenizer = tokenizer
        self.k1 = k1
        self.b = b
        self.doc_lengths: Dict[str, int] = {}
        self.term_doc_freq: Dict[str, int] = {}
        self.term_freqs: Dict[str, Dict[str, int]] = {}  # term -> {doc_id: count}
        total_len = 0
        for doc in documents:
            terms = tokenizer(doc.text)
            counts: Dict[str, int] = {}
            for term in terms:
                counts[term] = counts.get(term, 0) + 1
            self.doc_lengths[doc.id] = len(terms)
            total_len += len(terms)
            for term, count in counts.items():
                self.term_doc_freq[term] = self.term_doc_freq.get(term, 0) + 1
                self.term_freqs.setdefault(term, {})[doc.id] = count
        self.doc_count = max(1, len(self.doc_lengths))
        self.avg_dl = total_len / self.doc_count if self.doc_count else 0.0

    def idf(self, term: str) -> float:
        n = self.term_doc_freq.get(term, 0)
        return math.log(1.0 + (self.doc_count - n + 0.5) / (n + 0.5))

    def score(self, query_terms: Sequence[str], doc_id: str) -> float:
        dl = self.doc_lengths.get(doc_id, 0)
        if dl == 0:
            return 0.0
        score = 0.0
        for term in set(query_terms):
            tf = self.term_freqs.get(term, {}).get(doc_id, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1 - self.b + self.b * dl / max(self.avg_dl, 1e-9))
            score += self.idf(term) * (tf * (self.k1 + 1)) / denom
        return score


# ---------------------------------------------------------------------------
# Metadata-aware RAG engine
# ---------------------------------------------------------------------------


class MetadataAwareRAG:
    """Metadata-aware RAG engine.

    Pipeline per query:

      1. (Optional) structural metadata filtering -> candidate documents.
      2. Dense similarity (pluggable embedder) + BM25 lexical scoring.
      3. Hybrid relevance score ``alpha * dense + (1 - alpha) * lexical_norm``.
      4. Metadata ranking adjustments (priority/authority boost, recency decay).
      5. Top-k selection with an optional relevance threshold.
      6. Prompt/context assembly with numbered citations and an optional LLM
         callback for grounded answer generation.
    """

    DEFAULT_PROMPT = (
        "Use only the context below to answer the question. "
        "Cite sources with [n] markers matching the numbered items. "
        "If the context does not contain the answer, say "
        "\"I don't have enough information.\"\n\n"
        "Context:\n{context}\n\nQuestion: {question}\n\nAnswer:"
    )

    def __init__(
        self,
        embed_fn: Optional[Callable[[str], List[float]]] = None,
        tokenizer: Callable[[str], List[str]] = tokenize,
        alpha: float = 0.6,
        k1: float = 1.5,
        b: float = 0.75,
    ) -> None:
        if embed_fn is None:
            embed_fn = HashingVectorizer().embed
        self.embed_fn = embed_fn
        self.tokenizer = tokenizer
        self.alpha = alpha  # weight of dense vs lexical in hybrid relevance
        self.k1 = k1
        self.b = b
        self._documents: Dict[str, Document] = {}
        self._bm25: Optional[BM25Index] = None

    # -- indexing -----------------------------------------------------------

    def add_document(self, document: Document) -> None:
        if not document.embedding:
            document.embedding = self.embed_fn(document.text)
        self._documents[document.id] = document
        self._bm25 = None  # lexical index invalidated; rebuilt lazily

    def add_documents(self, documents: Iterable[Document]) -> int:
        count = 0
        for doc in documents:
            self.add_document(doc)
            count += 1
        return count

    @property
    def documents(self) -> Dict[str, Document]:
        return dict(self._documents)

    def _ensure_bm25(self) -> BM25Index:
        if self._bm25 is None:
            self._bm25 = BM25Index(
                self._documents.values(), self.tokenizer, k1=self.k1, b=self.b
            )
        return self._bm25

    # -- retrieval ----------------------------------------------------------

    def retrieve(
        self,
        query: str,
        metadata_filter: Optional[MetadataFilter] = None,
        k: int = 5,
        min_score: float = 0.0,
        boost_fields: Optional[Dict[str, float]] = None,
        decay_date_key: Optional[str] = None,
        decay_half_life_days: float = 365.0,
        now: Optional[datetime] = None,
    ) -> List[RetrievalResult]:
        """Retrieve and rank documents for ``query``.

        Args:
            query: user query text.
            metadata_filter: structural predicate; documents failing it are
                excluded before scoring (metadata-based FILTERING).
            k: number of top results to return.
            min_score: drop results whose final score is below this threshold.
            boost_fields: metadata keys whose numeric values multiply the
                relevance score, e.g. ``{"priority": 0.15, "authority": 0.1}``
                (metadata-based RANKING).
            decay_date_key: metadata key holding an ISO date or epoch used for
                a recency-decay multiplier ``0.5 ** (age_days / half_life)``.
            decay_half_life_days: half life of the recency decay curve.
            now: reference time for decay (defaults to current UTC time).
        """
        candidates = self._select_candidates(metadata_filter)
        if not candidates:
            return []

        query_embedding = self.embed_fn(query)
        query_terms = self.tokenizer(query)
        bm25 = self._ensure_bm25()
        lexical_scores = {doc.id: bm25.score(query_terms, doc.id) for doc in candidates}
        max_lex = max(lexical_scores.values()) if lexical_scores else 0.0

        results: List[RetrievalResult] = []
        for doc in candidates:
            dense = cosine_similarity(query_embedding, doc.embedding or [])
            lex = lexical_scores.get(doc.id, 0.0)
            lex_norm = lex / max_lex if max_lex > 0.0 else 0.0
            relevance = self.alpha * dense + (1.0 - self.alpha) * lex_norm

            adjustment = 1.0
            adjustment *= self._metadata_boost(doc.metadata, boost_fields or {})
            if decay_date_key is not None:
                adjustment *= self._recency_decay(
                    doc.metadata, decay_date_key, decay_half_life_days, now
                )

            final_score = relevance * adjustment
            if final_score >= min_score:
                results.append(
                    RetrievalResult(
                        document=doc,
                        score=final_score,
                        dense_score=dense,
                        lexical_score=lex,
                        metadata_adjustment=adjustment,
                    )
                )

        results.sort(key=lambda r: r.score, reverse=True)
        ranked = results[:k]
        for rank, res in enumerate(ranked, start=1):
            res.rank = rank
        return ranked

    def _select_candidates(
        self, metadata_filter: Optional[MetadataFilter]
    ) -> List[Document]:
        if metadata_filter is None:
            return list(self._documents.values())
        return [doc for doc in self._documents.values() if metadata_filter(doc.metadata)]

    # -- metadata ranking helpers -------------------------------------------

    @staticmethod
    def _metadata_boost(metadata: Dict[str, Any], boost_fields: Dict[str, float]) -> float:
        multiplier = 1.0
        for key, weight in boost_fields.items():
            value = metadata.get(key)
            if value is None:
                continue
            if isinstance(value, bool):
                multiplier *= 1.0 + weight if value else 1.0
            elif isinstance(value, (int, float)):
                multiplier *= 1.0 + weight * float(value)
        return multiplier

    @staticmethod
    def _parse_date(value: Any) -> Optional[datetime]:
        if isinstance(value, datetime):
            return value
        if isinstance(value, date):
            return datetime(value.year, value.month, value.day)
        if isinstance(value, (int, float)):
            try:
                return datetime.fromtimestamp(value)
            except (OverflowError, OSError, ValueError):
                return None
        if isinstance(value, str):
            text = value.strip()
            try:
                return datetime.fromisoformat(text)
            except ValueError:
                try:
                    return datetime.strptime(text, "%Y-%m-%d")
                except ValueError:
                    return None
        return None

    @classmethod
    def _recency_decay(
        cls,
        metadata: Dict[str, Any],
        date_key: str,
        half_life_days: float,
        now: Optional[datetime] = None,
    ) -> float:
        dt = cls._parse_date(metadata.get(date_key))
        if dt is None:
            return 1.0
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        ref = now or datetime.now(timezone.utc)
        if ref.tzinfo is None:
            ref = ref.replace(tzinfo=timezone.utc)
        age_days = max(0.0, (ref - dt).total_seconds() / 86400.0)
        return 0.5 ** (age_days / half_life_days)

    # -- answer generation --------------------------------------------------

    def format_context(self, results: Sequence[RetrievalResult], max_chars: int = 6000) -> str:
        parts: List[str] = []
        used = 0
        for i, res in enumerate(results, start=1):
            if used >= max_chars:
                break
            snippet = res.text.strip()
            if not snippet:
                continue
            parts.append(
                f"[{i}] (id={res.id}, metadata={res.document.metadata})\n{snippet}"
            )
            used += len(snippet)
        return "\n\n".join(parts)

    def answer(
        self,
        query: str,
        metadata_filter: Optional[MetadataFilter] = None,
        k: int = 5,
        llm: Optional[Callable[[str], str]] = None,
        prompt_template: Optional[str] = None,
        **retrieve_kwargs: Any,
    ) -> Dict[str, Any]:
        """End-to-end RAG query: retrieve, assemble context, generate answer.

        If ``llm`` is None a deterministic extractive fallback answer is
        produced from the top-ranked passages (each sentence tagged with its
        source citation), so the pipeline works without an external model.
        """
        results = self.retrieve(
            query, metadata_filter=metadata_filter, k=k, **retrieve_kwargs
        )
        context = self.format_context(results)
        template = prompt_template or self.DEFAULT_PROMPT
        prompt = template.format(context=context, question=query)

        if llm is not None:
            answer_text = llm(prompt)
        else:
            answer_text = self._extractive_answer(query, results)

        return {
            "question": query,
            "answer": answer_text,
            "context": context,
            "prompt": prompt,
            "results": results,
            "citations": [
                res.document.metadata.get("source", res.id) for res in results
            ],
            "filter": metadata_filter,
        }

    @staticmethod
    def _extractive_answer(query: str, results: Sequence[RetrievalResult]) -> str:
        """Ground the answer in the retrieved passages with citations."""
        query_tokens = tokenize(query)[:6]
        sentences: List[Tuple[str, int]] = []
        for idx, res in enumerate(results, start=1):
            for sent in re.split(r"(?<=[.!?])\s+", res.text.strip()):
                lowered = sent.lower()
                if len(sent) > 25 and any(tok in lowered for tok in query_tokens):
                    sentences.append((sent, idx))
        if not sentences:
            return "I don't have enough information in the retrieved context to answer."
        seen = set()
        unique: List[str] = []
        for sent, idx in sentences:
            key = sent.lower()
            if key not in seen:
                seen.add(key)
                unique.append(f"- {sent} [source {idx}]")
        return "Based on the retrieved documents:\n" + "\n".join(unique[:5])


